CREATE TABLE "gateway_call_keys" (
  "account" bigint PRIMARY KEY,
  "key_hash" text NOT NULL,
  "issued_at" bigint NOT NULL,
  "revoked_at" bigint
);

CREATE UNIQUE INDEX "gateway_call_keys_hash" ON "gateway_call_keys" (key_hash);

CREATE TABLE "gateway_requests" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "at" bigint NOT NULL,
  "account" bigint,
  "model" text NOT NULL,
  "run" text,
  "session" text,
  "input_tokens" bigint,
  "output_tokens" bigint,
  "cost_micros" bigint NOT NULL DEFAULT 0
);

CREATE INDEX "gateway_requests_run" ON "gateway_requests" (run) WHERE run IS NOT NULL;
CREATE INDEX "gateway_requests_session" ON "gateway_requests" (session, at) WHERE session IS NOT NULL;
CREATE INDEX "gateway_requests_account_at" ON "gateway_requests" (account, at);
